# zpq-dialect SQL for the prototype's cells (literal dates; zpq SQL has no DATE/INTERVAL literals).
q14() { echo "select sum(case when p_type like 'PROMO%' then l_extendedprice * (1 - l_discount) else 0 end) as promo, sum(l_extendedprice * (1 - l_discount)) as total from '$1/lineitem.parquet', '$1/part.parquet' where l_partkey = p_partkey and l_shipdate >= '1995-09-01' and l_shipdate < '1995-10-01'"; }
j2() { echo "select l_orderkey, sum(l_extendedprice * (1 - l_discount)) as revenue, o_orderdate from '$1/lineitem.parquet' join '$1/orders.parquet' on l_orderkey = o_orderkey group by l_orderkey, o_orderdate order by revenue desc, o_orderdate, l_orderkey limit 10"; }
q3() { echo "select l_orderkey, sum(l_extendedprice * (1 - l_discount)) as revenue, o_orderdate, o_shippriority from '$1/customer.parquet', '$1/orders.parquet', '$1/lineitem.parquet' where c_mktsegment = 'BUILDING' and c_custkey = o_custkey and l_orderkey = o_orderkey and o_orderdate < '1995-03-15' and l_shipdate > '1995-03-15' group by l_orderkey, o_orderdate, o_shippriority order by revenue desc, o_orderdate, l_orderkey limit 10"; }
# Stars (WP7): two publishing dimensions; then a third, filter-only, reduced to an IN.
s1() { echo "select o_orderpriority, p_brand, sum(l_extendedprice * (1 - l_discount)) as revenue, count(*) as n from '$1/lineitem.parquet', '$1/orders.parquet', '$1/part.parquet' where l_orderkey = o_orderkey and l_partkey = p_partkey and p_size < 10 and l_shipdate >= date '1995-01-01' group by o_orderpriority, p_brand order by revenue desc, o_orderpriority, p_brand limit 10"; }
s2() { echo "select o_orderpriority, p_brand, sum(l_extendedprice * (1 - l_discount)) as revenue, count(*) as n from '$1/lineitem.parquet', '$1/orders.parquet', '$1/part.parquet', '$1/supplier.parquet' where l_orderkey = o_orderkey and l_partkey = p_partkey and l_suppkey = s_suppkey and s_nationkey = 3 and p_size < 10 and l_shipdate >= date '1995-01-01' group by o_orderpriority, p_brand order by revenue desc, o_orderpriority, p_brand limit 10"; }
